   286  /* OPN -> Open up/renew the securechannel */
   287  static UA_StatusCode
   288  processOPN(UA_Server *server, UA_SecureChannel *channel,
   289             const UA_UInt32 requestId, const UA_ByteString *msg) {
   290      /* Decode the request */
   291      size_t offset = 0;
   292      UA_NodeId requestType;
   293      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   294      UA_OpenSecureChannelRequest openSecureChannelRequest;
   295      retval |= UA_NodeId_decodeBinary(msg, &offset, &requestType);
   296      retval |= UA_OpenSecureChannelRequest_decodeBinary(msg, &offset, &openSecureChannelRequest);
   297
   298      /* Error occured */
   299      if(retval != UA_STATUSCODE_GOOD ||
   300         requestType.identifier.numeric != UA_TYPES[UA_TYPES_OPENSECURECHANNELREQUEST].binaryEncodingId) {
   301          UA_NodeId_deleteMembers(&requestType);
   302          UA_OpenSecureChannelRequest_deleteMembers(&openSecureChannelRequest);
   303          UA_LOG_INFO_CHANNEL(server->config.logger, channel,
   304                              "Could not decode the OPN message. Closing the connection.");
   305          UA_SecureChannelManager_close(&server->secureChannelManager, channel->securityToken.channelId);
   306          return retval;
   307      }
   308
   309      /* Call the service */
   310      UA_OpenSecureChannelResponse openScResponse;
   311      UA_OpenSecureChannelResponse_init(&openScResponse);
   312      Service_OpenSecureChannel(server, channel, &openSecureChannelRequest, &openScResponse);
   313      UA_OpenSecureChannelRequest_deleteMembers(&openSecureChannelRequest);
   314      if(openScResponse.responseHeader.serviceResult != UA_STATUSCODE_GOOD) {
   315          UA_LOG_INFO_CHANNEL(server->config.logger, channel, "Could not open a SecureChannel. "
   316                              "Closing the connection.");
   317          UA_SecureChannelManager_close(&server->secureChannelManager,
   318                                        channel->securityToken.channelId);
   319          return openScResponse.responseHeader.serviceResult;
   320      }
   321
   322      /* Send the response */
   323      retval = UA_SecureChannel_sendAsymmetricOPNMessage(channel, requestId, &openScResponse,
   324                                                         &UA_TYPES[UA_TYPES_OPENSECURECHANNELRESPONSE]);
   325      UA_OpenSecureChannelResponse_deleteMembers(&openScResponse);
   326      if(retval != UA_STATUSCODE_GOOD) {
   327          UA_LOG_INFO_CHANNEL(server->config.logger, channel,
   328                              "Could not send the OPN answer with error code %s",
   329                              UA_StatusCode_name(retval));
   330          UA_SecureChannelManager_close(&server->secureChannelManager,
   331                                        channel->securityToken.channelId);
   332      }
   333      return retval;
   334  }
